function getInp(){let ix=(keys[KM.right]?1:0)-(keys[KM.left]?1:0),iy=(keys[KM.down]?1:0)-(keys[KM.up]?1:0);if(!ix&&!iy){ix=gax[0];iy=gax[1]}const m=hyp(ix,iy);if(m>1){ix/=m;iy/=m}if(v3a&&st=='play'&&cmode()==2){const fx=ct.x-cp.x,fz=ct.z-cp.z,fl=hyp(fx,fz)||1,ux=fx/fl,uz=fz/fl;return[ix*-uz-iy*ux,ix*ux-iy*uz]}return[ix,iy]}
